/*
 * The access and modification times of st, in the order futimens takes
 * them. POSIX.1-2008 names them st_atim and st_mtim; macOS calls them
 * st_atimespec and st_mtimespec (with _DARWIN_C_SOURCE, needed above).
 */
void platform_file_times(const struct stat *st, struct timespec times[2])
{
#ifdef __APPLE__
	times[0] = st->st_atimespec;
	times[1] = st->st_mtimespec;
#else
	times[0] = st->st_atim;
	times[1] = st->st_mtim;
#endif
}

#ifdef __APPLE__
/*
 * Whether the last part of argv[0] of pid is name. KERN_PROCARGS2 gives
 * argc, the executable's path, NULs to align, then the arguments. A
 * process that is gone or cannot be read does not match.
 */
static int argv0_is(pid_t pid, const char *name, char *buf, size_t cap)
{
	int mib[3] = { CTL_KERN, KERN_PROCARGS2, 0 };
	size_t size = cap;
	char *p, *end, *base;
	int argc;

	mib[2] = (int)pid;
	if (sysctl(mib, 3, buf, &size, NULL, 0) != 0 || size <= sizeof argc)
		return 0;
	memcpy(&argc, buf, sizeof argc);
	end = buf + size;
	p = memchr(buf + sizeof argc, '\0', size - sizeof argc);
	if (argc < 1 || p == NULL)
		return 0;
	while (p < end && *p == '\0')
		p++;
	if (p == end || memchr(p, '\0', (size_t)(end - p)) == NULL)
		return 0;
	base = strrchr(p, '/');
	return strcmp(base != NULL ? base + 1 : p, name) == 0;
}

/*
 * Whether a process of this user runs under name: as the kernel keeps it
 * (cut to MAXCOMLEN), or as the last part of argv[0]. The native Claude
 * Code starts through the symlink claude to versions/<version>, so the
 * kernel knows it as "2.1.314" and only argv[0] says "claude". 1 or 0,
 * -1 with errno when the list cannot be read. The list grows between
 * the two sysctl calls, hence the spare room.
 */
int platform_process_running(const char *name)
{
	int mib[4] = { CTL_KERN, KERN_PROC, KERN_PROC_ALL, 0 };
	int argmax_mib[2] = { CTL_KERN, KERN_ARGMAX };
	struct kinfo_proc *procs = NULL;
	size_t size, count, i, cap;
	char *args;
	uid_t uid;
	int found = 0, argmax;

	for (;;) {
		if (sysctl(mib, 4, NULL, &size, NULL, 0) != 0)
			return -1;
		size += size / 4 + sizeof *procs;
		procs = xrealloc(procs, size);
		if (sysctl(mib, 4, procs, &size, NULL, 0) == 0)
			break;
		if (errno != ENOMEM) {
			free(procs);
			return -1;
		}
	}
	uid = geteuid();
	count = size / sizeof *procs;
	for (i = 0; i < count && !found; i++)
		found = procs[i].kp_eproc.e_ucred.cr_uid == uid &&
		    strncmp(procs[i].kp_proc.p_comm, name, MAXCOMLEN) == 0;
	cap = sizeof argmax;
	if (!found && sysctl(argmax_mib, 2, &argmax, &cap, NULL, 0) == 0 &&
	    argmax > 0) {
		cap = (size_t)argmax;
		args = xmalloc(cap);
		for (i = 0; i < count && !found; i++)
			found = procs[i].kp_eproc.e_ucred.cr_uid == uid &&
			    argv0_is(procs[i].kp_proc.p_pid, name, args, cap);
		free(args);
	}
	free(procs);
	return found;
}
#endif

#ifdef __linux__
/* The first line or NUL-terminated string of a small /proc file. */
static int read_proc(const char *dir, const char *file, char *buf,
    size_t size)
{
	char *path, *end;
	ssize_t n;
	int fd;

	path = xjoin(dir, file);
	fd = open(path, O_RDONLY);
	free(path);
	if (fd < 0)
		return -1;
	n = read(fd, buf, size - 1);
	close(fd);
	if (n <= 0)
		return -1;
	buf[n] = '\0';
	end = strchr(buf, '\n');
	if (end != NULL)
		*end = '\0';
	return 0;
}

/*
 * Whether a process of this user runs under name: its comm (cut to 15
 * bytes by the kernel) or the last component of its argv[0]. 1 or 0, -1
 * with errno when /proc cannot be read.
 */
int platform_process_running(const char *name)
{
	struct dirent *e;
	struct stat st;
	char *dir, buf[4096], *base;
	const char *p;
	uid_t uid;
	DIR *d;
	int found = 0;

	d = opendir("/proc");
	if (d == NULL)
		return -1;
	uid = geteuid();
	while (!found && (e = readdir(d)) != NULL) {
		for (p = e->d_name; *p >= '0' && *p <= '9'; p++)
			;
		if (p == e->d_name || *p != '\0')
			continue;
		dir = xjoin("/proc", e->d_name);
		if (stat(dir, &st) == 0 && st.st_uid == uid) {
			if (read_proc(dir, "comm", buf, sizeof buf) == 0 &&
			    strncmp(buf, name, 15) == 0)
				found = 1;
			else if (read_proc(dir, "cmdline", buf, sizeof buf) == 0) {
				base = strrchr(buf, '/');
				found = strcmp(base != NULL ? base + 1 : buf,
				    name) == 0;
			}
		}
		free(dir);
	}
	closedir(d);
	return found;
}
#endif

/*
 * Directories where removable and network volumes appear when mounted.
 * A path below one of them whose volume is gone is unavailable, not
 * orphaned.
 */
#if defined(__APPLE__)
const char *const platform_mount_parents[] = { "/Volumes", NULL };
#elif defined(__linux__)
const char *const platform_mount_parents[] = {
	"/media", "/run/media", "/mnt", NULL
};
#else
const char *const platform_mount_parents[] = { NULL };
#endif

/*
 * The directory for the program's own data (the trash): never inside
 * Claude Code's directory. NULL when there is no home to put it in.
 */
char *platform_data_dir(const char *home)
{
#ifdef __APPLE__
	char *support, *dir;

	if (home == NULL)
		return NULL;
	support = xjoin(home, "Library/Application Support");
	dir = xjoin(support, "csm");
	free(support);
	return dir;
#else
	const char *xdg;
	char *share, *dir;

	/* XDG Base Directory: a relative value is invalid and ignored. */
	xdg = getenv("XDG_DATA_HOME");
	if (xdg != NULL && xdg[0] == '/')
		return xjoin(xdg, "csm");
	if (home == NULL)
		return NULL;
	share = xjoin(home, ".local/share");
	dir = xjoin(share, "csm");
	free(share);
	return dir;
#endif
}

/*
 * The directory for what the TUI remembers between runs: next to the
 * data on macOS, in the XDG state directory elsewhere.
 */
char *platform_state_dir(const char *home)
{
#ifdef __APPLE__
	return platform_data_dir(home);
#else
	const char *xdg;
	char *state, *dir;

	xdg = getenv("XDG_STATE_HOME");
	if (xdg != NULL && xdg[0] == '/')
		return xjoin(xdg, "csm");
	if (home == NULL)
		return NULL;
	state = xjoin(home, ".local/state");
	dir = xjoin(state, "csm");
	free(state);
	return dir;
#endif
}

/*
 * The columns and rows of the terminal on fd; -1 when it is not one.
 * TIOCGWINSZ is not in POSIX.1-2008, but every supported system has it.
 */
int platform_term_size(int fd, size_t *cols, size_t *rows)
{
	struct winsize ws;

	if (ioctl(fd, TIOCGWINSZ, &ws) != 0 || ws.ws_col == 0 ||
	    ws.ws_row == 0)
		return -1;
	*cols = ws.ws_col;
	*rows = ws.ws_row;
	return 0;
}

/*
 * The signal of a terminal resize. SIGWINCH is not in POSIX.1-2008, so
 * macOS hides it in strict mode (_DARWIN_C_SOURCE above shows it).
 */
int platform_resize_signal(void)
{
	return SIGWINCH;
}

/* Columns of the terminal on fd, or 0 when fd is not a terminal. */
size_t platform_term_width(int fd)
{
	struct winsize ws;

	if (!isatty(fd))
		return 0;
	if (ioctl(fd, TIOCGWINSZ, &ws) != 0 || ws.ws_col == 0)
		return 80;
	return ws.ws_col;
}
